1	/**
2	 * 晋升判定引擎
3	 */
4	
5	function checkPromotion(state) {
6	  const rank = state.corporate.rank;
7	  if (rank === "P10") return null;
8	
9	  const rankData = CORP_RANKS[rank];
10	  if (!rankData || !rankData.next) return null;
11	
12	  const reqs = rankData.promotionReqs;
13	  const c = state.player.corporate;
14	  const corp = state.corporate;
15	
16	  // 年龄检查
17	  if (state.player.age < rankData.minAge) return null;
18	
19	  // 能力
20	  if (reqs.minAbility && c.ability < reqs.minAbility) return null;
21	
22	  // 向上管理
23	  if (reqs.minUpward && c.upwardMgmt < reqs.minUpward) return null;
24	
25	  // 人缘
26	  if (reqs.minPopularity && c.popularity < reqs.minPopularity) return null;
27	
28	  // 绩效要求
29	  const recentPerfs = corp.perfHistory.slice(-3);
30	  if (reqs.minGrade && recentPerfs.length > 0) {
31	    const latestGrade = recentPerfs[recentPerfs.length - 1].grade;
32	    if (!gradeMeetsMin(latestGrade, reqs.minGrade)) return null;
33	  }
34	
35	  // 团队人数 (P7+)
36	  if (reqs.minTeamSize && corp.team.length < reqs.minTeamSize) return null;
37	
38	  // 重大项目 (P7+)
39	  if (
40	    reqs.minProjects &&
41	    (corp.completedProjects || []).length < reqs.minProjects
42	  )
43	    return null;
44	
45	  // P10特殊判定
46	  if (rank === "P9") {
47	    let chance = 0.6;
48	    chance += c.popularity * 0.002;
49	    chance += c.upwardMgmt * 0.002;
50	    if (Math.random() > chance) {
51	      StateManager.addMessage("🏛️ 董事会投票未通过...下次再试。", "warning");
52	      return null;
53	    }
54	  }
55	
56	  return rankData.next;
57	}
