59	function applyPromotion(state, newRank) {
60	  const oldRank = state.corporate.rank;
61	  state.corporate.rank = newRank;
62	  const rankData = CORP_RANKS[newRank];
63	
64	  // 晋升奖励
65	  state.player.corporate.ability = Math.min(
66	    100,
67	    state.player.corporate.ability + 5,
68	  );
69	  state.player.corporate.hair = Math.min(100, state.player.corporate.hair + 10);
70	  state.player.corporate.dignity = Math.min(
71	    100,
72	    state.player.corporate.dignity + 10,
73	  );
74	  state.player.corporate.kpi = Math.min(150, state.player.corporate.kpi + 15);
75	
76	  StateManager.addMessage(
77	    `🎉 恭喜晋升！${CORP_RANKS[oldRank].name} → ${rankData.name}！月薪调整为 ¥${rankData.baseSalary.toLocaleString()}`,
78	    "success",
79	  );
80	
81	  if (newRank === "P10") {
82	    checkCorpWinConditions(state);
83	  }
84	}
