91	function getPromotionProgress(state) {
92	  const rank = state.corporate.rank;
93	  if (rank === "P10") return { done: true, text: "已是最高职级！" };
94	
95	  const rankData = CORP_RANKS[rank];
96	  if (!rankData) return { done: false, text: "无法判定" };
97	
98	  const reqs = rankData.promotionReqs;
99	  const c = state.player.corporate;
100	  const corp = state.corporate;
101	
102	  const checks = [];
103	  if (reqs.minAbility)
104	    checks.push({ label: "能力", current: c.ability, target: reqs.minAbility });
105	  if (reqs.minUpward)
106	    checks.push({
107	      label: "向上管理",
108	      current: c.upwardMgmt,
109	      target: reqs.minUpward,
110	    });
111	  if (reqs.minPopularity)
112	    checks.push({
113	      label: "人缘",
114	      current: c.popularity,
115	      target: reqs.minPopularity,
116	    });
117	  if (reqs.minTeamSize)
118	    checks.push({
119	      label: "团队人数",
120	      current: corp.team.length,
121	      target: reqs.minTeamSize,
122	    });
123	  if (reqs.minProjects)
124	    checks.push({
125	      label: "重大项目",
126	      current: (corp.completedProjects || []).length,
127	      target: reqs.minProjects,
128	    });
129	
130	  const allMet = checks.every((ch) => ch.current >= ch.target);
131	  return { done: allMet, checks, nextRank: rankData.next };
132	}
