5	/** 执行职场行动 */
6	function doCorporateAction(actionId) {
7	  const state = StateManager.getState();
8	  const action = CORP_ACTIONS.find((a) => a.id === actionId);
9	  if (!action) return false;
10	
11	  // 检查职级要求
12	  if (action.requiresRank) {
13	    const rankIndex = ["P5", "P6", "P7", "P8", "P9", "P10"].indexOf(
14	      state.corporate.rank,
15	    );
16	    const requiredIndex = ["P5", "P6", "P7", "P8", "P9", "P10"].indexOf(
17	      action.requiresRank,
18	    );
19	    if (rankIndex < requiredIndex) {
20	      StateManager.addMessage(
21	        `⚠️ 需要${action.requiresRank}以上才能执行此操作。`,
22	        "warning",
23	      );
24	      return false;
25	    }
26	  }
27	
28	  // 检查费用
29	  if (action.cost && state.resources.cash < action.cost) {
30	    StateManager.addMessage(`⚠️ 需要 ¥${action.cost}，现金不足。`, "warning");
31	    return false;
32	  }
33	
34	  // 特殊处理：股票交易
35	  if (action.special === "stock") {
36	    showStockTradeModal();
37	    return true;
38	  }
39	
40	  // 扣费
41	  if (action.cost) {
42	    state.resources.cash -= action.cost;
43	  }
44	
45	  // 应用效果
46	  const c = state.player.corporate;
47	  const effects = action.effects;
48	  if (effects.kpi) c.kpi = Math.max(0, Math.min(150, c.kpi + effects.kpi));
49	  if (effects.ability)
50	    c.ability = Math.max(0, Math.min(100, c.ability + effects.ability));
51	  if (effects.hair) c.hair = Math.max(0, Math.min(100, c.hair + effects.hair));
52	  if (effects.dignity)
53	    c.dignity = Math.max(0, Math.min(100, c.dignity + effects.dignity));
54	  if (effects.upwardMgmt)
55	    c.upwardMgmt = Math.max(
56	      0,
57	      Math.min(100, c.upwardMgmt + effects.upwardMgmt),
58	    );
59	  if (effects.popularity)
60	    c.popularity = Math.max(
61	      0,
62	      Math.min(100, c.popularity + effects.popularity),
63	    );
64	  if (effects.risk) c.risk = Math.max(0, Math.min(100, c.risk + effects.risk));
65	  if (effects.fatigue)
66	    state.needs.fatigue = Math.max(
67	      0,
68	      Math.min(100, state.needs.fatigue + effects.fatigue),
69	    );
70	  if (effects.happiness)
71	    state.needs.happiness = Math.max(
72	      0,
73	      Math.min(100, state.needs.happiness + effects.happiness),
74	    );
75	  if (effects.intelligence)
76	    state.player.intelligence = Math.min(
77	      100,
78	      state.player.intelligence + effects.intelligence,
79	    );
80	
81	  state.corporate.actionsUsed++;
82	  StateManager.addMessage(`${action.icon} ${action.name}完成！`, "success");
83	
84	  // 检查季度是否用完
85	  const rankData = CORP_RANKS[state.corporate.rank];
86	  const maxActions = rankData ? rankData.maxActions : 3;
87	  if (state.corporate.actionsUsed >= maxActions) {
88	    endQuarter();
89	  }
90	
91	  return true;
92	}
93	
94	/** 季度结束 */
95	function endQuarter() {
96	  const state = StateManager.getState();
97	  const c = state.corporate;
98	
99	  // 绩效考核
100	  const perfResult = calculatePerfScore(state);
101	  const grade = assignGrade(perfResult.score, state);
102	  c.perfHistory.push({
103	    year: state.player.corpYear,
104	    quarter: state.player.corpQuarter,
105	    grade: grade.grade,
106	    score: perfResult.score,
107	  });
108	
109	  // 追踪连续C
110	  if (grade.grade === "C") {
111	    c.consecutiveC++;
112	  } else {
113	    c.consecutiveC = 0;
114	  }
115	
116	  // 发放季度工资
117	  const rankData = CORP_RANKS[c.rank];
118	  const salary = rankData ? rankData.baseSalary * 3 : 45000;
119	  state.resources.cash += salary;
120	  state.resources.totalEarned += salary;
121	
122	  StateManager.addMessage(
123	    `💰 Q${c.corpQuarter} 结束。工资到账 ¥${salary.toLocaleString()}。绩效: ${grade.grade}`,
124	    "success",
125	  );
126	
127	  // Q3 晋升判定
128	  if (c.corpQuarter === 3) {
129	    const promoResult = checkPromotion(state);
130	    if (promoResult) {
131	      applyPromotion(state, promoResult);
132	    }
133	  }
134	
135	  // 更新股票市场（延迟初始化+每季度行情刷新）
136	  if (
137	    typeof initStockMarket === "function" &&
138	    Object.keys(c.stockMarket || {}).length === 0
139	  ) {
140	    initStockMarket(state);
141	  }
142	  if (
143	    typeof updateStockPrices === "function" &&
144	    Object.keys(c.stockMarket || {}).length > 0
145	  ) {
146	    updateStockPrices(state, false);
147	  }
148	
149	  // 职场随机事件
150	  if (Math.random() < 0.2) {
151	    rollCorporateEvent(state);
152	  }
153	
154	  // 推进季度
155	  c.actionsUsed = 0;
156	  if (c.corpQuarter >= 4) {
157	    c.corpQuarter = 1;
158	    state.player.corpYear++;
159	    state.player.age++;
160	    StateManager.addMessage(
161	      `🎂 又一年过去了，你现在${state.player.age}岁了。`,
162	      "event",
163	    );
164	  } else {
165	    c.corpQuarter++;
166	  }
167	
168	  // 失败条件
169	  checkCorpLoseConditions(state);
170	  // 胜利条件
171	  checkCorpWinConditions(state);
172	
173	  autoSave();
174	}
