177	function enterCorporatePhase(companyId) {
178	  const state = StateManager.getState();
179	  const p = state.player;
180	
181	  const company =
182	    COMPANIES.find((c) => c.id === (companyId || "star_tech")) || COMPANIES[0];
183	
184	  p.phase = "corporate";
185	  p.corpYear = 1;
186	  p.corpQuarter = 1;
187	
188	  p.corporate.hair = 100;
189	  p.corporate.dignity = Math.min(100, Math.round(p.mental * 1.2));
190	  p.corporate.upwardMgmt = Math.min(
191	    100,
192	    Math.round(state.skills.sales.level * 0.8 + 15),
193	  );
194	  p.corporate.kpi = Math.min(
195	    150,
196	    Math.round(p.agility * 0.5 + state.skills.coding.level * 0.5 + 15),
197	  );
198	  p.corporate.ability = Math.min(
199	    100,
200	    Math.round(p.intelligence * 0.8 + state.skills.coding.level * 0.5 + 10),
201	  );
202	  p.corporate.risk = Math.min(100, 8 + Math.floor(Math.random() * 12));
203	  p.corporate.popularity = Math.min(
204	    100,
205	    Math.round(state.status.fame * 0.5 + 25),
206	  );
207	
208	  state.corporate.rank = "P5";
209	  state.corporate.company = company;
210	  state.corporate.joinedDay = p.day;
211	  state.corporate.actionsUsed = 0;
212	
213	  // 初始化股票市场
214	  if (typeof initStockMarket === "function") {
215	    initStockMarket(state);
216	    if (typeof bootstrapStockHistory === "function") {
217	      bootstrapStockHistory(state);
218	    }
219	  }
220	
221	  StateManager.addMessage(
222	    `🏢 入职 ${company.name}！从P5开始职场生涯。${company.culture}。`,
223	    "success",
224	  );
225	  StateManager.addMessage(
226	    "💡 做项目提升KPI，向上社交获取信任。每季度有行动次数限制。Q3有晋升答辩。",
227	    "info",
228	  );
229	
230	  document.querySelector(".modal-overlay")?.remove();
231	  currentTab = "actions";
232	  renderAll();
233	}
