1	/**
2	 * 绩效考核系统
3	 *
4	 * 综合评分 = KPI×0.35 + 能力×0.25 + 向上管理×0.20 + 人缘×0.15 + 团队×0.05
5	 * 评级 = 在20个模拟同事中的百分位排名
6	 */
7	
8	function calculatePerfScore(state) {
9	  const c = state.player.corporate;
10	
11	  let score = 0;
12	  score += c.kpi * 0.35;
13	  score += c.ability * 0.25;
14	  score += c.upwardMgmt * 0.2;
15	  score += c.popularity * 0.15;
16	
17	  // 团队贡献 (P7+)
18	  if (state.corporate.team.length > 0) {
19	    const avgProd =
20	      state.corporate.team.reduce((s, m) => s + (m.productivity || 5), 0) /
21	      state.corporate.team.length;
22	    score += avgProd * 0.05;
23	  }
24	
25	  // 惩罚项
26	  if (c.hair < 30) score -= 15;
27	  else if (c.hair < 50) score -= 5;
28	  if (c.dignity < 20) score -= 20;
29	  else if (c.dignity < 40) score -= 8;
30	  if (c.risk > 70) score -= 15;
31	  else if (c.risk > 50) score -= 5;
32	
33	  // 奖励项
34	  if (c.dignity > 80) score += 5;
35	  if (c.popularity > 80) score += 5;
36	
37	  // 随机方差 ±8%
38	  score += (Math.random() - 0.5) * score * 0.16;
39	  score = Math.max(0, Math.min(100, score));
40	
41	  return { score: Math.round(score) };
42	}
43	
44	function assignGrade(rawScore, state) {
45	  // 生成20个模拟同事的分数（围绕玩家分数聚类）
46	  const peerScores = [];
47	  const base = rawScore;
48	  for (let i = 0; i < 20; i++) {
49	    let ps = base + (Math.random() - 0.5) * 35;
50	    ps = Math.max(5, Math.min(100, ps));
51	    peerScores.push(Math.round(ps));
52	  }
53	
54	  const allScores = [...peerScores, rawScore];
55	  allScores.sort((a, b) => b - a);
56	  const rank = allScores.indexOf(rawScore);
57	  const percentile = rank / allScores.length;
58	
59	  let grade;
60	  if (rawScore < 25) grade = "C";
61	  else if (percentile < 0.05) grade = "S+";
62	  else if (percentile < 0.15) grade = "S";
63	  else if (percentile < 0.5) grade = "A";
64	  else if (percentile < 0.85) grade = "B";
65	  else grade = "C";
66	
67	  // 人缘极差时降级
68	  if (state.player.corporate.popularity < 20 && grade === "A") grade = "B";
69	
70	  return {
71	    grade,
72	    score: rawScore,
73	    peerAvg: Math.round(
74	      peerScores.reduce((a, b) => a + b, 0) / peerScores.length,
75	    ),
76	    percentile: Math.round((1 - percentile) * 100),
77	  };
78	}
79	
80	function getGradeColor(grade) {
81	  return (
82	    { "S+": "#ff6b6b", S: "#feca57", A: "#48dbfb", B: "#c8d6e5", C: "#ff9ff3" }[
83	      grade
84	    ] || "#ccc"
85	  );
86	}
87	
88	function getGradeBonus(grade) {
89	  return { "S+": 3, S: 2, A: 1.5, B: 1, C: 0 }[grade] || 0;
90	}
