1004	function endDay() {
1005	  const state = StateManager.getState();
1006	
1007	  state.player.day++;
1008	
1009	  // 使用需求系统模块
1010	  if (typeof applyNeedsDecay === "function") applyNeedsDecay(state);
1011	  else {
1012	    state.needs.hunger = Math.max(0, state.needs.hunger - 18);
1013	    state.needs.hygiene = Math.max(0, state.needs.hygiene - 8);
1014	  }
1015	  // 睡眠恢复（基础25 + 住所加成）
1016	  const house = getCurrentHousing(state);
1017	  state.needs.fatigue = Math.max(
1018	    0,
1019	    state.needs.fatigue - house.fatigueRecovery,
1020	  );
1021	  state.needs.hygiene = Math.min(
1022	    100,
1023	    state.needs.hygiene + (house.hygieneBonus || 0),
1024	  );
1025	  state.needs.happiness = Math.max(
1026	    0,
1027	    Math.min(100, state.needs.happiness - 3 + (house.happinessBonus || 0)),
1028	  );
1029	
1030	  // 扣房租
1031	  if (house.rent > 0) {
1032	    if (state.resources.cash >= house.rent) {
1033	      state.resources.cash -= house.rent;
1034	    } else {
1035	      StateManager.addMessage(
1036	        `⚠️ 付不起房租 ¥${house.rent}！被赶回流落街头。`,
1037	        "danger",
1038	      );
1039	      state.housing.tier = 0;
1040	      state.inventory.capacity = 20 + (state.housing?.storageCapacity || 0);
1041	    }
1042	  }
1043	  // 扣仓库租金
1044	  if (state.housing?.storageRented && state.housing?.storageCapacity > 0) {
1045	    const storageRent = state.housing.storageCapacity >= 500 ? 50 : 20;
1046	    if (state.resources.cash >= storageRent) {
1047	      state.resources.cash -= storageRent;
1048	    } else {
1049	      StateManager.addMessage("⚠️ 付不起仓库租金，仓库被收回。", "danger");
1050	      state.housing.storageRented = false;
1051	      state.housing.storageCapacity = 0;
1052	      const baseCap = [20, 50, 100, 200][state.housing.tier || 0];
1053	      state.inventory.capacity = baseCap;
1054	    }
1055	  }
1056	
1057	  // 伤病结算
1058	  if (typeof tickHealthStatus === "function") tickHealthStatus(state);
1059	  else {
1060	    if (!state.status.sick && !state.status.injured)
1061	      state.status.health = Math.min(100, state.status.health + 1);
1062	    if (state.status.sick) {
1063	      state.status.health = Math.max(0, state.status.health - 3);
1064	      if (Math.random() < 0.1) state.status.sick = false;
1065	    }
1066	    if (state.status.injured) {
1067	      state.status.health = Math.max(0, state.status.health - 2);
1068	      if (Math.random() < 0.05) state.status.injured = false;
1069	    }
1070	  }
1071	
1072	  // 需求阈值检查
1073	  if (typeof checkNeedsThresholds === "function") checkNeedsThresholds(state);
1074	
1075	  // 情绪判定
1076	  if (typeof determineEmotionalState === "function")
1077	    determineEmotionalState(state);
1078	
1079	  // 贷款利息
1080	  if (state.resources.debt > 0) {
1081	    const interest = Math.floor(
1082	      state.resources.debt * state.resources.dailyInterest,
1083	    );
1084	    if (interest > 0) {
1085	      state.resources.debt += interest;
1086	      StateManager.addMessage(
1087	        `🏦 欠款利息：+¥${interest}（欠款 ¥${state.resources.debt.toLocaleString()}）`,
1088	        "warning",
1089	      );
1090	    }
1091	  }
1092	
1093	  // 银行存款利息
1094	  if (state.resources.bankBalance > 0) {
1095	    const bankInterest = Math.floor(state.resources.bankBalance * 0.001);
1096	    if (bankInterest > 0) state.resources.bankBalance += bankInterest;
1097	  }
1098	
1099	  // 每3天更新价格
1100	  if (state.player.day - state.trade.lastPriceUpdate >= 3) {
1101	    if (typeof updateAllPrices === "function") updateAllPrices(state);
1102	  }
1103	
1104	  // 新闻事件
