152	/** 初始化股市 */
153	function initStockMarket(state) {
154	  if (!state.investment) state.investment = createDefaultInvestment();
155	  for (const stock of STOCK_LIST) {
156	    if (!state.investment.stockMarket[stock.symbol]) {
157	      state.investment.stockMarket[stock.symbol] = {
158	        price: stock.basePrice * (0.85 + Math.random() * 0.3),
159	        history: [],
160	        high20: stock.basePrice,
161	        low20: stock.basePrice,
162	        lastNewsDay: -999,
163	        _initialized: false,
164	      };
165	    }
166	  }
167	}
168	
169	/** 初始化时填入少量历史走势 */
170	function bootstrapStockHistory(state) {
171	  if (!state.investment) state.investment = createDefaultInvestment();
172	  for (const sym of Object.keys(state.investment.stockMarket)) {
173	    const market = state.investment.stockMarket[sym];
174	    const def = STOCK_LIST.find((s) => s.symbol === sym);
175	    if (!def || market._initialized) continue;
176	    market._initialized = true;
177	    let p = market.price / (0.85 + Math.random() * 0.3);
178	    for (let i = 0; i < 20; i++) {
179	      const change = 1 + (Math.random() - 0.5) * def.volatility;
180	      p = p * change;
181	      market.history.push({ day: state.player.day - (20 - i), price: p });
182	    }
183	    market.history.push({ day: state.player.day, price: market.price });
184	    market.high20 = Math.max(...market.history.map((h) => h.price));
185	    market.low20 = Math.min(...market.history.map((h) => h.price));
186	  }
187	}
