189	/** 更新股市价格（每日结算时调用） */
190	function updateStockPrices(state, forceNews = false) {
191	  if (!state.investment) state.investment = createDefaultInvestment();
192	  for (const stock of STOCK_LIST) {
193	    const market = state.investment.stockMarket[stock.symbol];
194	    if (!market) continue;
195	    const trend = stock.baseTrend;
196	    const noise = (Math.random() - 0.5) * 2 * stock.volatility;
197	    let meanReversion = 0;
198	    if (market.history.length >= 5) {
199	      const recent = market.history.slice(-5);
200	      const avg = recent.reduce((s, h) => s + h.price, 0) / recent.length;
201	      meanReversion = ((avg - market.price) / avg) * 0.15;
202	    }
203	    const change = 1 + trend + noise + meanReversion;
204	    market.price = Math.max(0.5, market.price * change);
205	    market.price = Math.round(market.price * 100) / 100;
206	
207	    // 新闻冲击 5%
208	    if (forceNews || Math.random() < 0.05) {
209	      const newsPool = STOCK_NEWS_TEMPLATES.find(
210	        (n) => n.symbol === stock.symbol,
211	      );
212	      if (newsPool && state.player.day - market.lastNewsDay > 3) {
213	        const news =
214	          newsPool.headlines[
215	            Math.floor(Math.random() * newsPool.headlines.length)
216	          ];
217	        market.price = Math.max(0.5, market.price * (1 + news.impact));
218	        market.price = Math.round(market.price * 100) / 100;
219	        market.lastNewsDay = state.player.day;
220	        StateManager.addMessage(
221	          `📊 [${stock.symbol}] ${news.text}`,
222	          news.impact > 0 ? "success" : "danger",
223	        );
224	      }
225	    }
226	    market.history.push({ day: state.player.day, price: market.price });
227	    if (market.history.length > 20) market.history.shift();
228	    market.high20 = Math.max(...market.history.map((h) => h.price));
229	    market.low20 = Math.min(...market.history.map((h) => h.price));
230	  }
231	}
