233	/** 买入股票 */
234	function buyStock(symbol, shares) {
235	  const state = StateManager.getState();
236	  if (!state.investment) state.investment = createDefaultInvestment();
237	  const market = state.investment.stockMarket[symbol];
238	  if (!market) {
239	    StateManager.addMessage("⚠️ 不存在的股票。", "danger");
240	    return false;
241	  }
242	  shares = Math.floor(shares);
243	  if (shares <= 0) {
244	    StateManager.addMessage("⚠️ 至少买入1股。", "warning");
245	    return false;
246	  }
247	  const cost = Math.round(market.price * shares * 100) / 100;
248	  if (state.resources.cash < cost) {
249	    StateManager.addMessage(
250	      `⚠️ 需要 ¥${cost.toLocaleString()}，现金不足。`,
251	      "danger",
252	    );
253	    return false;
254	  }
255	  state.resources.cash -= cost;
256	  const existing = state.investment.stockHoldings.find(
257	    (s) => s.symbol === symbol,
258	  );
259	  if (existing) {
260	    const totalShares = existing.shares + shares;
261	    existing.avgPrice =
262	      Math.round(
263	        ((existing.avgPrice * existing.shares + cost) / totalShares) * 100,
264	      ) / 100;
265	    existing.shares = totalShares;
266	  } else {
267	    state.investment.stockHoldings.push({
268	      symbol,
269	      name: STOCK_LIST.find((s) => s.symbol === symbol)?.name || symbol,
270	      shares,
271	      avgPrice: market.price,
272	    });
273	  }
274	  StateManager.addMessage(
275	    `📈 买入 ${symbol} ×${shares}股 @¥${market.price}，共 ¥${cost.toLocaleString()}`,
276	    "success",
277	  );
278	  return true;
279	}
