281	/** 卖出股票 */
282	function sellStock(symbol, shares) {
283	  const state = StateManager.getState();
284	  if (!state.investment) state.investment = createDefaultInvestment();
285	  const holding = state.investment.stockHoldings.find(
286	    (s) => s.symbol === symbol,
287	  );
288	  if (!holding || holding.shares < shares) {
289	    StateManager.addMessage("⚠️ 持仓不足。", "danger");
290	    return false;
291	  }
292	  const market = state.investment.stockMarket[symbol];
293	  const revenue = Math.round(market.price * shares * 100) / 100;
294	  const profit = revenue - holding.avgPrice * shares;
295	  state.resources.cash += revenue;
296	  state.resources.totalEarned += Math.max(0, profit);
297	  holding.shares -= shares;
