336	/** 初始化比特币 */
337	function initBitcoin(state) {
338	  if (!state.investment) state.investment = createDefaultInvestment();
339	  if (!state.investment.bitcoin.initialized) {
340	    state.investment.bitcoin.price = 200000 * (0.8 + Math.random() * 0.4);
341	    state.investment.bitcoin.initialized = true;
342	    // 倒推20天历史
343	    let p = state.investment.bitcoin.price;
344	    for (let i = 0; i < 20; i++) {
345	      const change = 1 + (Math.random() - 0.5) * 0.08;
346	      p = p * change;
347	      state.investment.bitcoin.history.push({
348	        day: state.player.day - (20 - i),
349	        price: p,
350	      });
351	    }
352	    state.investment.bitcoin.history.push({
353	      day: state.player.day,
354	      price: state.investment.bitcoin.price,
355	    });
356	  }
357	}
