359	/** 更新比特币价格（每日结算时调用） */
360	function updateBitcoinPrice(state) {
361	  if (!state.investment) state.investment = createDefaultInvestment();
362	  const btc = state.investment.bitcoin;
363	
364	  // 1) 恐慌贪婪指数更新（惯性+随机）
365	  const fgiDrift = (Math.random() - 0.5) * 15;
366	  const fgiInertia = (btc.fearGreedIndex - 50) * 0.1;
367	  btc.fearGreedIndex = Math.max(
368	    0,
369	    Math.min(100, btc.fearGreedIndex + fgiDrift + fgiInertia),
370	  );
371	
372	  // 2) 基础趋势：根据FGI
373	  let trend = 0;
374	  if (btc.fearGreedIndex > 75)
375	    trend = 0.008; // 极度贪婪→上涨
376	  else if (btc.fearGreedIndex > 55)
377	    trend = 0.003; // 贪婪→温和上涨
378	  else if (btc.fearGreedIndex < 25)
379	    trend = -0.01; // 极度恐惧→下跌
380	  else if (btc.fearGreedIndex < 45) trend = -0.003; // 恐惧→温和下跌
381	
382	  // 3) 减半效应：每1460天（4年）减半周期
383	  const halvingCycle = state.player.day % 1460;
384	  if (halvingCycle < 60)
385	    trend += 0.02; // 减半后60天牛市启动
386	  else if (halvingCycle < 365)
387	    trend += 0.005; // 减半后1年内偏牛
388	  else if (halvingCycle > 1200) trend += 0.003; // 下次减半前预期升温
389	
390	  // 4) 随机波动（比特币远高于股票波动）
391	  const noise = (Math.random() - 0.5) * 2 * 0.08;
392	
393	  // 5) 极端行情（2%概率）
394	  let extremeShock = 0;
395	  if (Math.random() < 0.02) {
396	    extremeShock = (Math.random() - 0.4) * 0.3; // 偏向下跌（暴跌更常见）
397	    const direction = extremeShock > 0 ? "暴涨" : "暴跌";
398	    StateManager.addMessage(
399	      `₿ 比特币${direction}！恐慌贪婪指数: ${Math.round(btc.fearGreedIndex)}`,
400	      extremeShock > 0 ? "success" : "danger",
401	    );
402	  }
403	
404	  // 6) 均值回归
405	  let meanReversion = 0;
406	  if (btc.history.length >= 5) {
407	    const recent = btc.history.slice(-5);
408	    const avg = recent.reduce((s, h) => s + h.price, 0) / recent.length;
409	    meanReversion = ((avg - btc.price) / avg) * 0.1;
410	  }
411	
412	  const change = 1 + trend + noise + extremeShock + meanReversion;
413	  btc.price = Math.max(10000, btc.price * change);
414	  btc.price = Math.round(btc.price * 100) / 100;
415	
416	  // 6) 比特币新闻（3%概率）
417	  if (Math.random() < 0.03) {
418	    const btcNews = [
419	      { text: "🏛️ 某国宣布比特币为法定货币", impact: 0.15 },
420	      { text: "🚫 某大国全面封杀加密货币交易", impact: -0.2 },
421	      { text: "🏢 华尔街巨头买入10亿美元比特币", impact: 0.12 },
422	      { text: "💀 交易所被黑，损失数十亿", impact: -0.15 },
423	      { text: "₿ 比特币ETF获批，机构资金涌入", impact: 0.18 },
424	      { text: "📉 监管层约谈挖矿企业，算力暴跌", impact: -0.1 },
425	    ];
426	    const news = btcNews[Math.floor(Math.random() * btcNews.length)];
427	    btc.price = Math.max(10000, btc.price * (1 + news.impact));
428	    btc.price = Math.round(btc.price * 100) / 100;
429	    StateManager.addMessage(
430	      `₿ ${news.text}`,
431	      news.impact > 0 ? "success" : "danger",
432	    );
433	  }
434	
435	  btc.history.push({ day: state.player.day, price: btc.price });
436	  if (btc.history.length > 20) btc.history.shift();
437	  btc.high20 = Math.max(...btc.history.map((h) => h.price));
438	  btc.low20 = Math.min(...btc.history.map((h) => h.price));
439	}
