441	/** 买入比特币（以最小单位 0.001 BTC 为单位） */
442	function buyBitcoin(btcAmount) {
443	  const state = StateManager.getState();
444	  if (!state.investment) state.investment = createDefaultInvestment();
445	  const btc = state.investment.bitcoin;
446	  if (btcAmount <= 0) {
447	    StateManager.addMessage("⚠️ 至少买入 0.001 BTC。", "warning");
448	    return false;
449	  }
450	  const cost = Math.round(btc.price * btcAmount * 100) / 100;
451	  if (state.resources.cash < cost) {
452	    StateManager.addMessage(
453	      `⚠️ 需要 ¥${cost.toLocaleString()}，现金不足。`,
454	      "danger",
455	    );
456	    return false;
457	  }
458	  state.resources.cash -= cost;
459	  // 计算新均价
460	  const totalBtc = btc.holding + btcAmount;
461	  btc.avgPrice =
462	    Math.round(((btc.avgPrice * btc.holding + cost) / totalBtc) * 100) / 100;
463	  btc.holding = Math.round(totalBtc * 1000) / 1000; // 精确到0.001
464	  StateManager.addMessage(
465	    `₿ 买入 ${btcAmount} BTC @¥${(btc.price / 1).toLocaleString()}，共 ¥${cost.toLocaleString()}`,
466	    "success",
467	  );
468	  return true;
469	}
