487	  const profitStr =
488	    profit >= 0
489	      ? `📈 盈利 ¥${Math.round(profit).toLocaleString()}`
490	      : `📉 亏损 ¥${Math.abs(Math.round(profit)).toLocaleString()}`;
491	  StateManager.addMessage(
492	    `₿ 卖出 ${btcAmount} BTC，¥${revenue.toLocaleString()}。${profitStr}`,
493	    profit >= 0 ? "success" : "warning",
494	  );
