871	/** 渲染简易K线 */
872	function renderKLine(history, currentPrice) {
873	  if (!history || history.length < 2)
874	    return '<div style="color:var(--text-muted);font-size:10px;">无历史数据</div>';
875	  const prices = history.map((h) => h.price);
876	  const max = Math.max(...prices, currentPrice);
877	  const min = Math.min(...prices, currentPrice);
878	  const range = max - min || 1;
879	  const w = 140,
880	    h = 40;
881	  const stepX = w / (history.length - 1);
882	  const points = history
883	    .map(
884	      (p, i) =>
885	        `${(i * stepX).toFixed(1)},${(h - ((p.price - min) / range) * h).toFixed(1)}`,
886	    )
887	    .join(" ");
888	  const firstPrice = history[0].price;
889	  const lastPrice = history[history.length - 1].price;
890	  const lineColor =
891	    lastPrice >= firstPrice ? "var(--success)" : "var(--danger)";
892	  const fillColor =
893	    lastPrice >= firstPrice ? "rgba(46,204,113,0.12)" : "rgba(231,76,60,0.12)";
894	  const fillPoints = `0,${h} ${points} ${w},${h}`;
895	  return `<svg width="${w}" height="${h}" style="display:block;margin-top:4px;"><polygon points="${fillPoints}" fill="${fillColor}" /><polyline points="${points}" fill="none" stroke="${lineColor}" stroke-width="1.5" /></svg>`;
896	}
