683	      state.flags.yuEBao += interest;
684	    }
685	  }
686	  // 保险检查
687	  if (
688	    state.flags.hasInsurance &&
689	    state.flags.insuranceExpire < state.player.day
690	  ) {
691	    state.flags.hasInsurance = false;
692	    StateManager.addMessage("🛡️ 你的保险到期了，记得续保。", "info");
693	  }
694	  if (state.flags.hasInsurance && (state.status.injured || state.status.sick)) {
695	    if (!state.flags._insurancePaidThisCycle) {
696	      state.resources.cash += 500;
697	      state.flags._insurancePaidThisCycle = true;
698	      StateManager.addMessage("🛡️ 保险赔付了 ¥500！", "success");
699	    }
700	  }
701	  if (!state.status.injured && !state.status.sick) {
702	    state.flags._insurancePaidThisCycle = false;
703	  }
704	}
